using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace AboutMe.Editor
{
    public static class PartyGuardTests
    {
        static readonly FieldInfo Cache=typeof(CampusGeometry).GetField("solids",BindingFlags.NonPublic|BindingFlags.Static);
        static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
        public static PersonaInstance Throw(Match m,Vector3 position,Vector3 velocity,string who="p1")
        {var item=m.Items.First(x=>x.ownerId==who&&x.state==ItemState.Inventory);item.state=ItemState.Thrown;item.thrownBy=who;item.position=position;item.velocity=velocity;item.pushScale=1;item.guardTouches.Clear();return item;}
        public static EffectState Shot(Match m,Vector3 position,Vector3 velocity,string kind="Projectile")
        {var e=new EffectState{id=Guid.NewGuid().ToString("N"),kind=kind,owner="p1",position=position,velocity=velocity,remaining=2,damage=10,force=4,heavy=true};m.Effects.Add(e);return e;}
        public static void Run()
        {
            int passed=0;var old=Cache.GetValue(null);Cache.SetValue(null,new[]{new CampusSolid{name="Ground",center=new Vector3(0,-.5f,0),size=new Vector3(80,1,64)}});
            var failures=new System.Collections.Generic.List<string>();
            void Test(string name,Action run){try{run();passed++;Debug.Log("PARTY_GUARD_PASS "+name);}catch(Exception ex){failures.Add(name+": "+ex.Message);Debug.LogError("PARTY_GUARD_FAIL "+name+": "+ex);}}
            try
            {
                Test("front shield lands two real Persona without changing owner or life count",()=>{using(var m=PartyFieldTests.Make("front-shield")){var e=PartyFieldTests.Deploy(m);for(int i=0;i<2;i++){var shot=Throw(m,new Vector3(0,1.2f,3),Vector3.back*10);string id=shot.id;PartyFieldTests.Tick(m,.22f);Check(shot.id==id&&shot.ownerId=="p1"&&shot.state==ItemState.Ground&&m.Players["p0"].stability==100&&m.Remaining("p1")==4,"shield deleted/stole/harmed actual life");}Check(!m.Effects.Contains(e)&&m.CombatEvents.Count(x=>x.kind=="party_block")==2,"shield hit budget wrong");}});
                Test("shield rear and melee remain effective",()=>{using(var m=PartyFieldTests.Make("front-shield")){PartyFieldTests.Deploy(m);m.Hit(m.Players["p0"],m.Players["p1"],10,4,false);Check(m.Players["p0"].stability==90,"shield immune to melee");PartyFieldTests.Tick(m,.7f);var a=m.Players["p0"];a.position=new Vector3(0,1,0);a.motorHeight=1;a.impulse=Vector3.zero;var shot=Throw(m,new Vector3(0,1.2f,-3),Vector3.forward*10);PartyFieldTests.Tick(m,.35f);Check(m.Items.Count(x=>x.ownerId=="p0"&&x.state==ItemState.Ground)==1,"rear hit did not drop one life");}});
                Test("parry redirects actual life with causal thrower and unchanged original owner",()=>{using(var m=PartyFieldTests.Make("timed-reflect")){var e=PartyFieldTests.Deploy(m);var shot=Throw(m,new Vector3(0,1.2f,3),Vector3.back*10);PartyFieldTests.Tick(m,.16f);Check(shot.ownerId=="p1"&&shot.thrownBy=="p0"&&shot.velocity.z>0&&e.stage=="parried"&&m.Players["p0"].stability==100,"reflection did not preserve owner or reverse causal velocity");Check(m.CombatEvents.Count(x=>x.kind=="party_reflect")==1&&m.Remaining("p0")==4&&m.Remaining("p1")==4,"reflection duplicated life or event");}});
                Test("parry missed window has public expiry and recovery lock",()=>{using(var m=PartyFieldTests.Make("timed-reflect")){var e=PartyFieldTests.Deploy(m);PartyFieldTests.Tick(m,.56f);Check(!m.Effects.Contains(e)&&m.Players["p0"].nextAttack>m.Time+.2f&&m.Events.Last().text.Contains("窗口结束"),"parry failure lacked recovery feedback");}});
                Test("anchor holds horizontal kick but admits vertical force and depleted drop",()=>{using(var m=PartyFieldTests.Make("ground-anchor")){PartyFieldTests.Deploy(m);var a=m.Players["p0"];m.Hit(a,m.Players["p1"],10,4,false);Check(a.stability==90&&Mathf.Abs(a.impulse.x)<.001f,"anchor removed damage or admitted horizontal kick");PartyFieldTests.Tick(m,.3f);m.Hit(a,m.Players["p1"],100,4,true,impulseOverride:new Vector3(5,4,0));Check(a.impulse.y>3&&Mathf.Abs(a.impulse.x)<.001f&&m.Items.Count(x=>x.ownerId=="p0"&&x.state==ItemState.Ground)==1,"anchor erased vertical hit or duplicated life");}});
                Test("anchor prevents pure drag while held Q and expiry remain available",()=>{using(var m=PartyFieldTests.Make("ground-anchor")){PartyFieldTests.Deploy(m);var a=m.Players["p0"];var b=m.Players["p1"];b.position=new Vector3(0,1,-1.5f);b.grabbing="p0";b.grabStartedAt=m.Time;b.grabberLocalAnchor=Vector3.forward;b.targetLocalAnchor=Vector3.zero;PartyFieldTests.Tick(m,.5f,"p1",0,-1);Check(Mathf.Abs(a.position.z)<.1f&&a.stability<100,"anchor did not brace or made grab harmless");PartyFieldTests.Input(m,"p0","cancel");Check(!m.GuardAnchored(a),"Q did not cancel anchor");}});
                Test("bank stores one nonfatal impulse with normal damage and one bounded return",()=>{using(var m=PartyFieldTests.Make("impact-bank")){var e=PartyFieldTests.Deploy(m);var a=m.Players["p0"];var b=m.Players["p1"];m.Hit(a,b,20,4,false);Check(a.stability==80&&a.impulse.magnitude<.001f&&e.stage=="banked"&&e.force>0&&e.force<=6,"bank did not absorb just impulse");float stored=e.force;m.Hit(a,b,20,4,false);Check(a.stability==60&&a.impulse.magnitude>1&&e.force==stored,"bank reabsorbed second attack");PartyFieldTests.Tick(m,.45f);b.position=a.position+Vector3.forward*2;PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,.18f);Check(!m.Effects.Contains(e)&&b.stability==100&&b.position.z>2&&m.CombatEvents.Count(x=>x.kind=="party_bank_return")==1,"bank return repeated or harmed life");}});
                Test("ribbon blocks rear once and front remains exposed",()=>{using(var m=PartyFieldTests.Make("ribbon-cover")){var e=PartyFieldTests.Deploy(m);var rear=Throw(m,new Vector3(0,1.2f,-3),Vector3.forward*10);PartyFieldTests.Tick(m,.23f);Check(rear.state==ItemState.Ground&&!m.Effects.Contains(e)&&m.Players["p0"].stability==100,"rear cover failed");var front=Throw(m,new Vector3(0,1.2f,3),Vector3.back*10);PartyFieldTests.Tick(m,.3f);Check(m.Items.Count(x=>x.ownerId=="p0"&&x.state==ItemState.Ground)==1,"front incorrectly protected");}});
                Test("recovery screen blocks once but characters can walk through it",()=>{using(var m=PartyFieldTests.Make("recover-screen")){var e=PartyFieldTests.Deploy(m);PartyFieldTests.Tick(m,.6f,"p0",0,1);Check(m.Players["p0"].position.z>e.position.z+.1f&&m.Effects.Contains(e),"screen blocked character motion");}using(var n=PartyFieldTests.Make("recover-screen")){var e=PartyFieldTests.Deploy(n);var shot=Throw(n,new Vector3(0,1.2f,3),Vector3.back*10);PartyFieldTests.Tick(n,.23f);Check(shot.state==ItemState.Ground&&!n.Effects.Contains(e)&&n.Players["p0"].stability==100,"screen did not land shot safely");}});
                Test("dome scales horizontal impact only; actual projectile still depletes one life",()=>{using(var m=PartyFieldTests.Make("calm-dome")){PartyFieldTests.Deploy(m);var shot=Throw(m,new Vector3(0,2,5),new Vector3(0,4,-10));PartyFieldTests.Tick(m,.55f);var hit=m.CombatEvents.LastOrDefault(x=>x.kind=="hit"&&x.targetId=="p0");Check(hit!=null&&Mathf.Abs(new Vector2(hit.impulse.x,hit.impulse.z).magnitude-2.45f)<.02f&&Mathf.Abs(hit.impulse.y-3)<.01f,"dome changed wrong impact component hit="+(hit==null?"none":hit.impulse.ToString())+" scale="+shot.pushScale+" shot="+shot.position);Check(shot.pushScale==.35f&&m.Items.Count(x=>x.ownerId=="p0"&&x.state==ItemState.Ground)==1&&m.Remaining("p0")==4,"dome healed or stole life");}});
                Test("wind bends actual projectile once without pushing people or changing owner",()=>{using(var m=PartyFieldTests.Make("wind-deflector")){PartyFieldTests.Deploy(m);var shot=Throw(m,new Vector3(0,1.3f,2.5f),Vector3.back*8);PartyFieldTests.Tick(m,.04f);Check(shot.velocity.x< -5&&shot.thrownBy=="p1"&&shot.ownerId=="p1","wind failed to redirect safely");PartyFieldTests.Tick(m,.5f);Check(m.CombatEvents.Count(x=>x.kind=="party_deflect")==1&&m.Players["p0"].stability==100&&m.Players["p0"].position.z==0,"wind repeated or pushed person");}});
                Test("rhythm closed phase blocks but open phase passes identical shot",()=>{foreach(bool closed in new[]{false,true})using(var m=PartyFieldTests.Make("rhythm-gate")){var e=PartyFieldTests.Deploy(m);if(closed)PartyFieldTests.Tick(m,.4f);Throw(m,new Vector3(0,1.1f,2.2f),Vector3.back*10);PartyFieldTests.Tick(m,.15f);Check(closed?e.health==1&&m.Players["p0"].stability==100:m.Items.Any(x=>x.ownerId=="p0"&&x.state==ItemState.Ground),"rhythm timing did not change interception");}});
                Test("sponge clears exactly two wet points and never removes glue or source life",()=>{using(var m=PartyFieldTests.Make("sponge-dry")){var source=m.Players["p1"].equipped;var wet=new EffectState{id="wet",kind="PartyMechanic",mechanicId="wet-trail",owner="p1",sourceInstance=source,position=new Vector3(10,1,0),deadline=m.Time+5,path=new[]{new Vector3(0,.15f,1.8f),new Vector3(.4f,.15f,1.8f),new Vector3(.8f,.15f,1.8f),new Vector3(10,.15f,0)},nextHit=m.Time+5};var glue=new EffectState{id="glue",kind="PartyMechanic",mechanicId="sticky-step",owner="p1",sourceInstance=source,position=new Vector3(0,.15f,1.8f),radius=2,deadline=m.Time+5};m.Effects.Add(wet);m.Effects.Add(glue);var e=PartyFieldTests.Deploy(m);Check(wet.path.Length==2&&e.chainIndex==2&&e.stage=="saturated"&&m.Effects.Contains(glue)&&m.Remaining("p1")==4,"drying removed wrong region or life");}});
                Test("standard projectile/disc/public box share guards; blast remains effective",()=>{foreach(var kind in new[]{"Projectile","Disc","ThrownDisc","Ricochet"})using(var m=PartyFieldTests.Make("front-shield")){var shield=PartyFieldTests.Deploy(m);Shot(m,new Vector3(0,1.2f,3),Vector3.back*10,kind);PartyFieldTests.Tick(m,.25f);Check(shield.health==1&&m.Players["p0"].stability==100,"standard shot bypassed shield: "+kind);}using(var m=PartyFieldTests.Make("front-shield")){var shield=PartyFieldTests.Deploy(m);var box=new PublicProp{id="box",visual="box",position=new Vector3(0,1.3f,3),velocity=Vector3.back*10,thrower="p1"};m.Props.Add(box);PartyFieldTests.Tick(m,.25f);Check(box.thrower==""&&shield.health==1&&m.Players["p0"].stability==100,"public box bypassed shield");m.Hit(m.Players["p0"],m.Players["p1"],25,6,true,impulseOverride:Vector3.right*6);Check(m.Players["p0"].stability==75,"shield blocked area damage");}});
                Test("shield does not catch through solid wall",()=>{using(var m=PartyFieldTests.Make("front-shield")){var e=PartyFieldTests.Deploy(m);Cache.SetValue(null,new[]{new CampusSolid{name="Ground",center=new Vector3(0,-.5f,0),size=new Vector3(80,1,64)},new CampusSolid{name="wall",center=new Vector3(0,1,2.2f),size=new Vector3(4,2,.2f)}});var shot=Throw(m,new Vector3(0,1.2f,3),Vector3.back*10);PartyFieldTests.Tick(m,.35f);Check(e.health==2&&m.Players["p0"].stability==100&&shot.state==ItemState.Ground,"wall failed or shield intercepted through it");}Cache.SetValue(null,new[]{new CampusSolid{name="Ground",center=new Vector3(0,-.5f,0),size=new Vector3(80,1,64)}});});
                Test("shield leaves normal grab available",()=>{using(var m=PartyFieldTests.Make("front-shield")){var e=PartyFieldTests.Deploy(m);var b=m.Players["p1"];b.position=new Vector3(0,1,-1.1f);b.yaw=0;PartyFieldTests.Input(m,"p1","grab");PartyFieldTests.Tick(m,.3f);Check(b.grabbing=="p0"&&!m.Effects.Contains(e),"grab did not counter held shield");}});
                Test("anchor applies to tether and publishes its reduced impulse",()=>{using(var m=PartyFieldTests.Make("ground-anchor")){PartyFieldTests.Deploy(m);var a=m.Players["p0"];var b=m.Players["p1"];b.position=new Vector3(0,1,-2);b.yaw=0;m.Item(b.equipped).asset.templateId="Tether";PartyFieldTests.Input(m,"p1","use_item");PartyFieldTests.Tick(m,.25f);Check(new Vector2(a.impactImpulse.x,a.impactImpulse.z).magnitude<.01f&&a.stability==100&&a.position.z==0,"tether or public impulse bypassed anchor");}});
                Test("public dome boundary matches authoritative sphere above ground",()=>{using(var m=PartyFieldTests.Make("calm-dome")){var e=PartyFieldTests.Deploy(m);var go=PartyMechanicVisual.Create(e,null);try{go.GetComponent<PartyMechanicVisual>().Present(e,m.Time,null,m.View("p0"));var center=e.position+Vector3.up*.85f;foreach(var line in go.GetComponentsInChildren<LineRenderer>())for(int i=0;i<line.positionCount;i++){var point=line.transform.TransformPoint(line.GetPosition(i));Check(Mathf.Abs(Vector3.Distance(point,center)-e.radius)<.01f&&point.y>=.059f,"visible dome differs from interception boundary");}}finally{UnityEngine.Object.DestroyImmediate(go);}}});
                Test("Q/equipment/consume/disconnect cleanup preserve owner counts",()=>{foreach(var mode in new[]{"cancel","equip","consume","disconnect"})using(var m=PartyFieldTests.Make("front-shield")){var e=PartyFieldTests.Deploy(m);if(mode=="cancel")PartyFieldTests.Input(m,"p0","cancel");if(mode=="equip"){PartyFieldTests.Tick(m,.45f);var a=m.Players["p0"];m.Receive("p0",new Command{sequence=a.sequence+1,action="equip",itemId=m.Items.First(x=>x.ownerId=="p0"&&x.state==ItemState.Inventory).id});}if(mode=="consume")m.Item(e.sourceInstance).state=ItemState.Consumed;if(mode=="disconnect")m.Disconnect("p0");PartyFieldTests.Tick(m,.02f);Check(!m.Effects.Contains(e),"guard cleanup failed: "+mode);m.Finish("timeout");Check(!m.Effects.Any(x=>x.kind=="PartyMechanic"),"finish retained guards");}});
            }
            finally{Cache.SetValue(null,old);}
            if(failures.Count>0)throw new Exception(string.Join("\n",failures));Debug.Log("PARTY_GUARDS_PASSED "+passed+" authority scenarios / ten distinct defensive mechanics / real Persona and public prop identity conserved");
        }
    }
}
